RSpec.describe Timekeeping::BillingFence do
  # "Create `Timekeeping::BillingFence` in `app/services/timekeeping/billing_fence.rb` with one entry point that
  # opens the billing transaction, takes FOR SHARE on the ownership row, and raises a retryable
