RSpec.describe Timekeeping::BillingFence, "guard on billing models" do
  def start_billing_fence_handoff
    TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).update_all(handoff_step: "settle")
  end

  it "refuses an invoice save, a line-item destroy and an invoice-tax save made outside any wrapper" do
    invoice = create(:invoice, status: :draft)
    line_item = create(:invoice_line_item, invoice:)
    tax = create(:invoice_tax, invoice:)
    original_reference = invoice.reload.reference
    original_tax_name = tax.reload.name
    start_billing_fence_handoff

    expect { invoice.update!(reference: "REF-HANDOFF") }
      .to raise_error(Timekeeping::BillingFence::OwnershipMoving)
    expect { InvoiceLineItem.find(line_item.id).destroy }
      .to raise_error(Timekeeping::BillingFence::OwnershipMoving)
    expect { InvoiceTax.find(tax.id).update!(name: "Handoff tax") }
      .to raise_error(Timekeeping::BillingFence::OwnershipMoving)

    expect(invoice.reload.reference).to eq(original_reference)
    expect(InvoiceLineItem.where(id: line_item.id)).to exist
    expect(tax.reload.name).to eq(original_tax_name)
  end

  it "refuses billing writes of every company during a handoff and admits them without one" do
    first_company = create(:company)
    second_company = create(:company)
    first_invoice = create(:invoice, company: first_company, client: create(:client, company: first_company))
    second_invoice = create(:invoice, company: second_company, client: create(:client, company: second_company))

    expect { first_invoice.update!(reference: "REF-A") }.not_to raise_error
    expect { second_invoice.update!(reference: "REF-B") }.not_to raise_error

    start_billing_fence_handoff

    [first_invoice, second_invoice].each do |invoice|
      expect { invoice.update!(reference: "REF-NO") }.to raise_error(Timekeeping::BillingFence::OwnershipMoving)
    end
    expect([first_invoice.reload.reference, second_invoice.reload.reference]).to eq(["REF-A", "REF-B"])
  end
end
